/* SETTINGS — the only place to tune the SYSTEM.
 *
 * What lives here: shared scales (space, type, radius, motion) and knobs used
 * by FAMILIES of components (controls, cards, popovers) or the app layout.
 * What does NOT live here: dimensions used by a single component — those are
 * co-located in that component's own CSS (e.g. modal widths in Modal.css,
 * switch size in Switch.css). See CLAUDE.md "token conventions".
 *
 * Unit convention:
 *   - grid-aligned sizes (control heights, rails)   → calc(var(--grid-unit) * N)
 *   - independent layout widths / max-widths        → rem
 *   - type scale                                     → rem
 */

:root {
  /* ════ FOUNDATION SCALES ════════════════════════════════════════ */

  /* Space — grid-unit is the SINGLE base unit (4pt grid). All --space-* in
   * primitives.css are integer multiples of it. Fixed: it's a decision, not a
   * live knob — to retune density, change it here in source. */
  --grid-unit: 4px;
  --space-2xs: 2px; /* sub-grid hairline (badge pad, switch thumb gap, dividers) */

  /* Type — explicit, independently-tunable steps (no ratio/fluid math). Each is
   * a fixed value picked by eye; small steps grow gently (12→13→15→17), large
   * ones jump (44→56). --font-md fills the base→lg gap. To rescale, edit here.
   *   xs/sm  captions, subtext      base  body / UI
   *   lg/xl  small headings         2xl/3xl page / document titles
   *   4xl/5xl large display / hero */
  --font-xs: 0.75rem; /* 12px */
  --font-sm: 0.8125rem; /* 13px */
  --font-base: 0.9375rem; /* 15px — body / UI */
  --font-md: 1.0625rem; /* 17px — large body / subheads (fills the base→lg gap) */
  --font-lg: 1.25rem; /* 20px */
  --font-xl: 1.5rem; /* 24px */
  --font-2xl: 1.875rem; /* 30px */
  --font-3xl: 2.25rem; /* 36px */
  --font-4xl: 2.75rem; /* 44px */

  /* @brand:typography — regenerated by `npm run rebrand` */
  --font-family:         'Onest', ui-sans-serif, system-ui, sans-serif;
  --font-family-display: 'Commissioner', 'Onest', ui-sans-serif, system-ui, sans-serif;
  --font-family-mono:    ui-monospace, 'Menlo', monospace;
  /* @brand:end */

  /* Weights — all four are real faces, not synthesised: both brand families are
   * VARIABLE fonts, so one file per script covers the whole range (see
   * brand/system/manifest.json). A brand shipping static files must supply one
   * per weight, or the browser fakes the missing ones. */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Line-height + letter-spacing. */
  --leading-none: 1; /* single-line numerics */
  --leading-tight: 1.15; /* headings */
  --leading-snug: 1.3; /* compact UI */
  --leading-normal: 1.5; /* body */
  --leading-relaxed: 1.65; /* long-form prose (report bodies) */
  --tracking-wide: 0.08em;

  /* Shape — radius scale (radius-* computed in primitives.css from these). */
  --radius: 8px; /* base (md) radius — keep a multiple of the grid */
  --radius-rect: calc(
    var(--radius) + var(--grid-unit) * 4
  ); /* soft rounded-rect (textarea, multi-line composer) — follows the radius knob, on-grid */

  /* Motion. Durations AND the curve, because a duration without a curve is
   * half a decision: everything that had no `transition-timing-function` fell
   * back to CSS `ease`, which starts fast and ends slow — the shape a thing
   * makes when it is thrown, not when it answers. One curve for the system.
   *
   * --ease-out is THE curve: fast off the mark, settling into the end state.
   * --ease-in-out is for something that leaves and comes back (a drawer, a
   * carousel slide), where both ends need to be soft.
   *
   * The rule the card was breaking (owner, 23.08: the animation on the cards is
   * jerky, it should be smooth and crisp): ONE gesture moves at ONE speed. The
   * hover used to run a 120ms shadow, a 200ms scrim and a 320ms zoom at once,
   * so the parts of a single card arrived one after another. */
  --duration-fast: 120ms;
  --duration-normal: 200ms;
  --duration-slow: 320ms;
  --ease-out: cubic-bezier(0.2, 0, 0, 1);

  /* Focus ring — single source for the universal focus-visible outline. */
  --ring-width: 2px;
  --ring-offset: 2px;

  /* Breakpoints — @media can't read custom props, so values are duplicated
   * literally in @media rules. This is the source of truth / documentation. */
  --bp-sm: 30rem; /* 480px  — small phones up */
  --bp-md: 48rem; /* 768px  — tablets up */
  --bp-lg: 62rem; /* 992px  — laptops up */
  --bp-xl: 75rem; /* 1200px — desktops up */
  --bp-2xl: 100rem; /* 1600px — wide screens up */

  /* Color — palette is hardcoded hex in primitives.css (50 light → 900 dark).
   * Change brand colors there; semantic roles map them in semantic.css. */

  /* ════ COMPONENT-FAMILY KNOBS ═══════════════════════════════════ */

  /* ONE LADDER: 32 / 40 / 48. Every part a reader can stand beside another part
   * in a row uses it — buttons, inputs, selects, textareas, segmented toggles
   * AND avatars. Three rungs, eight apart, and nothing between them.
   *
   * `lg` was 52 and is 48 (owner, 2026-08-29). 52 is a 4-multiple and it was
   * defended as one, but it is not a rung: 32 to 40 is eight and 40 to 52 is
   * twelve, so the ladder had no step and a large control could not be matched
   * by anything else. A scale whose gaps differ is not a scale, it is three
   * numbers.
   *
   * Heights are fixed rather than derived: only padding follows --grid-unit
   * density, because a control that changes height with the spacing grid stops
   * lining up with the one beside it. */
  --control-height-sm: 2rem; /* 32px — compact buttons/chips */
  --control-height: 2.5rem; /* 40px */
  --control-height-lg: 3rem; /* 48px — block/CTA buttons */
  /* @brand:control-radius — regenerated by `npm run rebrand` */
  --control-radius:       var(--radius-full);
  /* @brand:end */
  --control-padding-x: var(--space-6);
  --control-font-size: var(--font-base); /* md (default) */
  --control-font-size-lg: 1rem; /* lg — one modest notch up (16px) */
  --control-font-weight: var(--font-weight-semibold);

  /* Elevation — shadows shared by cards/popovers (shadow-sm/md/lg in primitives). */
  --shadow-popover: 0 4px 24px rgb(0 0 0 / 0.08);
  /* Soft, and actually visible. It was 0 0 24px at 6% black — a glow so faint
   * that the only feedback a card gave under the pointer was the cursor. A lift
   * has a direction: a small downward offset reads as the card coming up off the
   * page, which is what the gesture means. */
  --shadow-card-hover: 0 6px 20px rgb(0 0 0 / 0.12);

  /* Cards. */
  --card-radius: var(--radius-xl);
  /* The picture keeps its SHAPE, not its height. A fixed 9rem made the same
   * card's media a 2.6:1 letterbox in a grid column and a 5.2:1 strip across a
   * feature row, so the same component looked like two different ones on one
   * screen (owner, 22.08: the cards do not look designed). */
  --card-media-ratio: 16 / 9;
  --card-padding: var(--space-6); /* 24px */
  /* The same room as the parent. It was 12px, then 16px, and the owner called
   * both cramped (2026-08-22): a nested card holds the same kind of content the
   * outer one does — an avatar, a name, an action — and content does not need
   * less air for sitting one level in. The concentric radius and the outline
   * say "inside"; the padding does not have to say it as well. The knob stays,
   * so a dense product can still tighten it in one place. */
  --card-padding-nested: var(--space-6); /* 24px */
  --card-shadow: var(--shadow-popover);
  /* One step above body, not four. At --font-xl a card title was 24px over 13px metadata: the
   * name shouted and nothing under it had a rank, which is why every card in every app read as a
   * title with some grey text stuck to it. See the CARD ANATOMY block in Card.css. */
  --card-title-size: var(--font-lg); /* every <CardTitle> / section head. md read as body text beside 13px meta (owner, 2026-08-21); lg makes the rank visible at card-grid glance distance. */

  /* Popover surfaces (dropdown / select / menu) — concentric radii: the surface
   * rounds like a small card; rows inside round one step less. */
  --popover-radius: var(--radius-lg);
  --popover-item-radius: var(--radius-md);

  /* THE TWO ROOMS A FLOATING SURFACE GIVES, and they are two questions rather
   * than one taste. A surface carrying CONTENT — a popover, a hover card, the
   * palette's field — pads it like a small card. A surface that is a FRAME
   * around rows — a menu, a listbox — pads only enough to keep the first row off
   * the edge, because the rows carry their own padding and doubling it makes a
   * menu look like a card with a list in it.
   *
   * They were five separate numbers in five stylesheets until 2026-09-03, which
   * is one family answering one question five ways: a brand retuning its popover
   * density had five files to find and no way to know it had found them. */
  --popover-padding: var(--space-4);
  --popover-frame-padding: var(--space-1);

  /* ════ VISUAL SCALES ════════════════════════════════════════════ */

  /* Icons — FIXED sizes, multiples of 4 (legibility, not spacing-density). */
  --icon-sm: 1rem; /* 16px — inline with text, in buttons */
  --icon-md: 1.25rem; /* 20px — navigation, lists */
  --icon-lg: 1.5rem; /* 24px — emphasis, hero */
  --icon-xl: 2.5rem; /* 40px — empty states */
  --icon-2xl: 5rem; /* 80px — large empty-state illustrations */
  --icon-stroke: 2; /* line thickness for all icons (= Lucide default; 1.5 read too thin) */

  /* Avatars stand ON THE CONTROL LADDER, because a face in a row stands beside
   * controls: a header is a search box, a button and a person, and until today
   * the person was a rung short of both — `md` meant 32 here and 40 there, so
   * `<Avatar size="md">` beside `<Button>` sat 8px low and the row did not
   * read as a line (owner, 2026-08-29).
   *
   * The names now mean one thing across the system. `xl` and `2xl` are off the
   * ladder on purpose: they are not in a row with anything, they are the hero
   * on a profile screen, and a control that size does not exist. */
  --avatar-sm: var(--control-height-sm); /* 32px — in a row */
  --avatar-md: var(--control-height);    /* 40px — beside a title */
  --avatar-lg: var(--control-height-lg); /* 48px — leading a card */
  --avatar-xl: 5rem; /* 80px — hero, off the ladder */
  --avatar-2xl: 8rem; /* 128px — profile header, off the ladder */

  /* ════ LAYOUT ═══════════════════════════════════════════════════ */

  /* App sidebar. */
  --sidebar-width: 16.25rem; /* 260px — expanded */
  --sidebar-rail-item-size: 2.5rem; /* 40px — collapsed icon button (fixed component size) */

  /* Content widths. */
  --page-max-width: 96rem; /* cap for header + main content (was 80rem; one tier up) */
  /* The whole shell: nav column + capped content. Past this the composition
   * stops growing and centres on the screen instead, so a 2560px monitor gets
   * equal margins on both sides rather than a nav pinned to the left edge and
   * a content column that reads 130px right of centre. 112rem = the 96rem cap
   * plus the 16.25rem nav, rounded to the scale. */
  --shell-max-width: 112rem;
  --prose-max-width: 32rem; /* narrative / error pages */
  --side-panel-width: 24rem; /* right rail content panel (Comments/Versions/etc) */

  /* Chat template (AssistantPage). */
  --chat-sidebar-width: 22.5rem; /* 360px — chat-history list column */
  --chat-panel-width: 24rem; /* right-side form panel */
  --chat-message-max-width: 44rem; /* readable message column */

  /* Brand marks (used by Sidebar + LoginPage). */
}

/* PRIMITIVES — computed tokens.
 *
 * Color scales: hardcoded hex, Tailwind-style naming (50 = lightest, 900 = darkest).
 * Brand pivots around #4638D3 (indigo) at the 400 stop.
 * If you need a different palette, replace hex values here — no formulas. */

:root {
  /* Space — multiples of grid-unit */
  --space-1: calc(var(--grid-unit) * 1);
  --space-2: calc(var(--grid-unit) * 2);
  --space-3: calc(var(--grid-unit) * 3);
  --space-4: calc(var(--grid-unit) * 4);
  /* 20. Added 2026-08-26 on the owner's call, and the reason is a real gap: the
     ladder doubled after 4 and jumped 16 → 24, so a distance a screen genuinely
     wanted between those two could only be reached by stacking two tokens — and
     a sum is not a decision. The page audit reads the scale rather than a copy
     of it, so it accepted this step the moment it existed. */
  --space-5: calc(var(--grid-unit) * 5);
  --space-6: calc(var(--grid-unit) * 6);
  --space-8: calc(var(--grid-unit) * 8);
  --space-12: calc(var(--grid-unit) * 12);
  --space-16: calc(var(--grid-unit) * 16);

  /* Fluid spacing for section gaps (grows with viewport width) */

  /* Font sizes are now an explicit scale in settings.css (no computed steps). */

  /* ── Color scales — the system's own palette ─────
   * Primary stops vary by family:
   *   brand   primary = 400 (#4638D3 indigo)
   *   success primary = 800 (lime family, pivots at 500)
   *   warning primary = 700 (yellow)
   *   danger  primary = 500 (coral)
   *   gray    primary = 700 (body text)
   */

  /* @brand:colors — regenerated by `npm run rebrand` from brand/<active>/manifest.json */
  --brand-50:  #edecfc;
  --brand-100: #d8d5f9;
  --brand-200: #b7b2f2;
  --brand-300: #8680e7;
  --brand-400: #4638d3;   /* Primary */
  --brand-500: #3b2fb6;
  --brand-600: #33289c;
  --brand-700: #2a2181;
  --brand-800: #211a66;
  --brand-900: #171247;
  /* @brand:end */

  /* Neutrals (Gray) */
  --neutral-0:   #ffffff;
  --neutral-50:  #f6fbff;
  --neutral-100: #f1f6fd;
  --neutral-200: #ebf0f7;
  --neutral-300: #dde2e9;
  --neutral-400: #bbbfc6;
  --neutral-500: #9ca0a7;
  /* THE EDGE STOP. The one neutral that clears 3:1 against every surface this
   * system paints, in both themes: white 3.48, page 3.20, accent 3.04, popover
   * 3.76, card 4.20, dark page 4.54. Added because the top of this ramp is
   * compressed — white to neutral-300 is 1.30:1 — so no existing stop could
   * carry the boundary of a control (WCAG 1.4.11 wants 3:1). Everything that
   * says "this is a control, and it ends here" resolves to this: --input,
   * --switch-track-off, --control-edge. */
  --neutral-550: #858a91;
  --neutral-600: #73777d;
  --neutral-700: #5f6369;  /* Primary (body text) */
  /* THE DARK-THEME SURFACE SCALE. Four stops, ~1.2:1 apart, and BOTH halves of
   * that — how far apart they are, and how dark the whole ramp sits — were paid
   * for on the same day.
   *
   * They used to be 1.08:1 apart, the same RATIO the light theme uses between
   * its page and its cards. The eye does not read a ratio, it reads a
   * difference, and at this end of the ramp 1.08:1 is nothing: a page of cards
   * came out as one flat grey wash (owner, 30.08).
   *
   * The first fix bought that separation by pulling the PAGE up to #363a3f, and
   * a dark theme whose largest area is mid-grey is not a dark theme — it read as
   * washed out (owner, 30.08, hours later). The separation is the same size now
   * and the ramp sits a stop lower: the page went back to where it was and the
   * CARD came down to meet it. Darkening the small shape costs nothing;
   * lightening the large one costs the theme.
   *
   *   950  the quiet fill  — a control that must not dissolve into any surface
   *   900  the CARD        — content sits DARKER than the page it is on
   *   820  the PAGE        — background and its tint, the lightest large area
   *   800  edges and lifts — borders, popovers, hover
   *
   * Cards darker than the page is deliberate and it is the reverse of the light
   * theme, where white cards lift off a tinted page. In dark the light-theme
   * order (card lighter than bg) puts the two brightest greys next to each other
   * and neither wins; a well reads instantly.
   *
   * 900 carries two jobs — the light theme's body ink and this theme's card —
   * which is what a ramp is for: one value, named once. The 850 stop it replaced
   * is gone; nothing outside these four lines referenced it. */
  --neutral-800: #3b3f45;  /* dark-theme edge, popover and hover surface */
  --neutral-820: #2c3036;  /* dark-theme PAGE (background + its muted tint) */
  --neutral-900: #1f2328;  /* light-theme body ink, and the dark-theme CARD */
  --neutral-950: #0e1217;  /* dark-theme quiet control fill, a step under the card */

  /* Scrim stops: the ink-alpha ramp under text that sits over imagery. Alpha
   * on a near-black, never on pure black — pure black scrims go muddy. */
  --scrim-0:   rgb(16 19 24 / 0);
  --scrim-70:  rgb(16 19 24 / 0.72);
  --scrim-85:  rgb(16 19 24 / 0.85);

  /* Success (Lime green, pivots around #84BD00 at the 500 stop; 800 stays
   * the primary text/surface stop, dark enough for white-on-green). */
  --success-50:  #f4f9e6;
  --success-100: #e3f0c2;
  --success-200: #cde59a;
  --success-300: #b3d96b;
  --success-400: #9ccb38;
  --success-500: #84bd00;
  --success-600: #76a900;
  --success-700: #659200;
  --success-800: #527700;  /* Primary */
  --success-900: #3c5800;

  /* Warning (Yellow) */
  --warning-50:  #fffee9;
  --warning-100: #fffac8;
  --warning-200: #fff6a3;
  --warning-300: #fef17f;
  --warning-400: #fcec63;
  --warning-500: #f9e74a;
  --warning-600: #ffde4d;
  --warning-700: #ffc846;  /* Primary */
  --warning-800: #fcb03e;
  --warning-900: #f68930;
  /* Dark-theme tinted SURFACE. The yellow ramp never gets dark (900 is a
   * saturated orange), so dark mode had no legible soft-warning background —
   * this stop is that surface. Not part of the light ramp. */
  /* The dark theme's soft tint. The ramp falls from a bright amber at 900 straight
   * to the ink stop at 950, so "warning, quietly" in dark landed at 1.05:1 on a
   * card — the pill was gone and only its yellow text was left, floating (owner,
   * 30.08). This sits at the same luminance as --success-900, which is the one
   * tone that always read, so the four tones now tint by the same amount. */
  --warning-930: #6b4915;
  --warning-950: #3a2a05;

  /* Danger (Red / coral) */
  --danger-50:  #feedef;
  --danger-100: #fdd2d4;
  --danger-200: #eca39f;
  --danger-300: #e2817a;
  --danger-400: #eb6858;
  --danger-500: #f05e41;   /* Primary */
  --danger-600: #e1553f;
  --danger-700: #cf4b39;
  --danger-800: #c24633;
  --danger-900: #b13e29;
  /* Dark-theme tinted SURFACE — same reason as --warning-950: the coral ramp
   * stays light enough that danger-900 cannot host readable text in dark mode. */
  --danger-930: #8d3122;   /* dark-theme soft tint — see --warning-930 */
  --danger-950: #3b1410;

  /* Violet — the AI accent. Deliberately outside the brand ramp: "generated by
   * the assistant" has to read as a different KIND of thing from the product's
   * own colour, in every brand this system is re-skinned into. */
  --violet-50:  #f5f3ff;
  --violet-100: #ede9fe;
  --violet-200: #ddd6fe;
  --violet-300: #c4b5fd;
  --violet-400: #a78bfa;
  --violet-500: #8b5cf6;
  --violet-600: #7c3aed;   /* Primary */
  --violet-700: #6d28d9;
  --violet-800: #5b21b6;
  --violet-900: #4c1d95;

  /* Shadows */
  /* ════ CHART SERIES ════════════════════════════════════════════════
   * Six hues for CATEGORICAL data — one series, one hue, assigned in this fixed
   * order and never cycled. Slot 1 is the brand indigo, so a single-series
   * chart is the brand's own colour; the other five are picked to stay apart
   * under protanopia and deuteranopia, not by eye.
   *
   * Measured, not chosen: the set passes the lightness band, the chroma floor,
   * adjacent-pair CVD separation (worst 9.1 light / 8.4 dark, OKLab x100,
   * target >= 8) and the normal-vision floor (19.6 light / 19.3 dark, floor 15)
   * on white and on the dark card surface. Three light-mode hues sit under 3:1
   * against white, which is why every chart in this system carries direct
   * labels or a legend rather than colour alone.
   *
   * The `-dark` steps are the same six hues restepped for the dark surface —
   * not an automatic lightening, and validated as their own set. */
  /* Series 1 IS the brand, and now says so rather than repeating its hex. The
     comment always claimed the relationship; the code did not, so a rebrand
     moved the brand and left chart series 1 on the old indigo (audit,
     2026-08-26). Same for its dark step. */
  --series-1:      var(--brand-400);
  --series-2:      #eb6834;  /* orange */
  --series-3:      #1baf7a;  /* aqua */
  --series-4:      #eda100;  /* yellow */
  --series-5:      #e87ba4;  /* magenta */
  --series-6:      #008300;  /* green */
  --series-1-dark: var(--brand-300);
  --series-2-dark: #d95926;
  --series-3-dark: #199e70;
  --series-4-dark: #c98500;
  --series-5-dark: #d55181;
  /* This green reads on both surfaces, so its dark step is the light one —
     stated, not coincidentally retyped. */
  --series-6-dark: var(--series-6);

  --shadow-sm: 0 1px 2px rgb(0 0 0 / 0.08);
  --shadow-md: 0 2px 16px rgb(0 0 0 / 0.06);
  --shadow-lg: 0 12px 32px rgb(0 0 0 / 0.14);

  /* Radius — scale steps by the grid unit, so every tier stays on-grid.
   * (--radius is the md tier; sm is one grid step down, lg/xl steps up.) */
  --radius-sm: max(0px, calc(var(--radius) - var(--grid-unit)));
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + var(--grid-unit));
  --radius-xl: calc(var(--radius) + var(--grid-unit) * 2);
  --radius-full: 9999px;

  /* Gradient — brand sweep (login screen). */

  /* Z-index — sticky lowest, then modals, then dropdowns (so Selects inside
   * a Modal render above it), then toasts, then tooltips on top. */
  --z-sticky:    50;
  --z-modal:     100;
  --z-dropdown:  200;
  --z-toast:     300;
  --z-tooltip:   400;
}

/* SEMANTIC — role tokens.
 *
 * Light = values mirror the reference prototype:
 *   bg-primary    = white         → --background
 *   bg-secondary  = gray-50       → --muted (page surface in AppShell)
 *   text-primary  = neutral-900   → --foreground  (dark gray ≈ this stop)
 *   text-secondary= gray-700      → --secondary-foreground (in some contexts)
 *   text-tertiary = gray-600      → --muted-foreground
 *   primary       = brand-400     → --primary
 *   border        = ~8% black     → --neutral-200 (visually equivalent)
 *
 * Dark = inverted with three-tier surface (bg < muted < card).
 */

/* `:root` holds the light defaults. `[data-theme-lock="light"]` shares them so a
 * subtree (e.g. the login screen) can stay light even when the app is dark — it
 * re-declares these tokens directly on the element, beating the inherited
 * `[data-theme="dark"]` values from <html>. Shadows are reset just below. */
:root { color-scheme: light dark; }

:root,
[data-theme-lock="light"] {
  --background:             var(--neutral-0);     /* white body */
  --foreground:             var(--neutral-900);   /* primary text — close to sa-dark-gray */

  --card:                   var(--neutral-0);
  --card-foreground:        var(--neutral-900);

  --popover:                var(--neutral-0);
  --popover-foreground:     var(--neutral-900);

  --muted:                  var(--neutral-100);   /* page surface — body bg (gray-100) */
  /* neutral-700, not -600: secondary text also sits on --muted surfaces (the
   * app background, table heads, side panels), where -600 reached only 4.15:1
   * and missed AA. -700 is 5.57:1 there and 6.04:1 on white, and still reads as
   * clearly secondary against --foreground (neutral-900, 15.8:1). */
  --muted-foreground:       var(--neutral-700);

  --primary:                var(--brand-400);     /* #4638D3 brand indigo */
  --primary-foreground:     var(--neutral-0);
  --primary-hover:          var(--brand-500);
  /* Pressed. Hover moves one stop, the press moves one more — the third
   * step the system did not have. */
  --primary-active:         var(--brand-600);
  /* LINKS. There was no such token and no Link component, so every link in the
   * system had picked its own colour by hand: the link-button brand, EntityLink
   * near-black, the breadcrumb grey, a card title inheriting. Four answers to
   * one question, side by side on the same screen. One decision now:
   *   --link        text that goes somewhere, inside reading text
   *   --link-quiet  the same thing in chrome, where position already says it
   * Deliberately NOT :visited: these are application links, and a workspace
   * whose nav recolours itself as you use it reads as broken rather than as
   * helpful. A content site should add it here and nowhere else. */
  --link:                   var(--primary-accent);
  --link-hover:             var(--primary-hover);
  --link-quiet:             var(--muted-foreground);
  /* Primary used as TEXT / icon / border ON a page or card surface (not a fill).
   * Same as --primary in light; the dark theme lightens it so brand-blue accents
   * stay legible on the dark surface (brand-400 there sits at ~1.7:1 — it blends).
   * Fills (buttons, the blue action band, primary badges) keep --primary. */
  --primary-accent:         var(--brand-400);
  /* Soft brand surface — tinted bg + saturated text (selected chips, soft badges, info toast). */
  --primary-soft:           var(--brand-50);
  --primary-soft-foreground: var(--brand-700);

  /* AI accent — anything the assistant generated or is about to. Violet on purpose,
   * so it never collides with the product's own brand colour after a re-skin. */
  --ai:                     var(--violet-600);
  --ai-foreground:          var(--neutral-0);
  --ai-soft:                var(--violet-50);
  --ai-soft-foreground:     var(--violet-700);

  --icon-muted:             var(--neutral-500);

  /* ════ CHARTS ═══════════════════════════════════════════════════
   * The series slots a chart paints with, in fixed order: series 1 is always
   * --chart-1, whatever else is on screen, so a filter that drops a series
   * never repaints the ones that stay. Status colours (--success, --warning,
   * --destructive) are NOT in this list on purpose: a chart that means "how
   * much of it is bad" tones by meaning, and a chart that means "these are
   * three different things" tones by slot. Mixing them makes one series look
   * like a warning. */
  --chart-1: var(--series-1);
  --chart-2: var(--series-2);
  --chart-3: var(--series-3);
  --chart-4: var(--series-4);
  --chart-5: var(--series-5);
  --chart-6: var(--series-6);
  /* The furniture: a grid line is the quietest thing on the plot, an axis label
   * is ordinary secondary text, and the track is what an unfilled bar sits in. */
  --chart-grid:  var(--border);
  --chart-axis:  var(--muted-foreground);
  --chart-track: var(--accent);
  /* Status, as DATA rather than as a chip. A donut painted in --success /
   * --warning / --destructive came out olive, mustard and brick (owner, 23.08:
   * this looks bad): those steps are chosen to carry white TEXT on a small
   * badge, and a 40px arc of the same colour is a different job. These are the
   * same three meanings, one step fresher, and they are only ever used for a
   * filled area that carries its own label.
   *
   * They are deliberately NOT run through the categorical adjacency gate: a
   * status palette separates by meaning and ships with a named legend, which is
   * the documented mitigation. */
  --chart-success: var(--success-600);
  --chart-warning: var(--warning-800);
  --chart-danger:  var(--danger-600);


  /* The FILL of this pair went on 2026-09-02: nothing in the system painted
   * with it, and the rule is that a token nobody takes is deleted rather than
   * carried. The ink stayed because Chip takes it. A half-used pair is worth
   * noticing — if a part ever needs the fill back it is --neutral-100 in light
   * and --neutral-950 in dark, which is what it was. */
  --secondary-foreground:   var(--neutral-700);   /* text-secondary */

  --accent:                 var(--neutral-200);
  --accent-foreground:      var(--neutral-900);
  /* Softer hover/active fill for elements ON white/elevated surfaces (menus,
   * lists, toolbar icon buttons) — lighter than --accent. */
  /* neutral-200, not -100: at -100 this token WAS --muted, so a ghost button
   * or a menu row hovering on the page surface painted itself the exact
   * colour of the page — 1.00:1, a hover that does not happen. The step has
   * to differ from every surface it can land on, not merely be quiet. */
  --accent-soft:            var(--neutral-200);
  /* One stop past --accent: the hover step for a control that already carries a
   * fill (a pill, a filled icon button), so hovering moves it FURTHER from the
   * surface behind it rather than back towards it. */
  --accent-strong:          var(--neutral-300);
  /* One past --accent-strong: the pressed step for a control on a card, where
   * hover has already spent --accent-strong. */
  --accent-active:         var(--neutral-400);
  /* One past pressed: what a quiet control on a WHITE surface is held down
   * at, now that its resting fill starts a step lower. */
  /* WHAT A QUIET CONTROL FILLS ITSELF WITH SO IT DOES NOT DISSOLVE INTO ITS
   * SURFACE: on grey go white, on white go grey.
   *
   * This is the page's answer. Every surface that is NOT the page has to give
   * its own, and that is the part which used to be missing: only `.card` did,
   * so a quiet button on any other white area took this answer and stood white
   * on white. `.content-surface` in the showcase is exactly that — a white area
   * the code calls "not a card" — and its Start Editing button had no fill at
   * all (owner, 2026-08-23). The rule was right; it was only bound in one file.
   *
   * A surface answering is now checked rather than remembered: the showcase's
   * `npm run controls` walks every screen and measures every filled control
   * against the colour actually painted behind it. */
  --surface-contrast:       var(--card);
  --surface-contrast-hover: var(--accent);
  /* The third step: what the same control fills itself with WHILE PRESSED. The
   * system had hover and then nothing — no `:active` rule existed anywhere in
   * 106 components, so a click gave no answer until the work finished and a
   * slow action read as a dead button. One more stop in the same direction. */
  --surface-contrast-active: var(--accent-strong);
  /* Hover/active fill for a row inside a POPOVER surface, which is a different
   * surface from the page. In dark, --accent-soft and --popover are both
   * neutral-820: every menu highlight was painting itself the exact colour of
   * the menu (1.00:1), so hover and the keyboard position were invisible. A
   * popover states its own step. */
  --popover-hover:          var(--neutral-100);
  /* Row/area hover on a card surface: one whisper lighter than the page tint,
   * so a hovered table row reads without ever matching --muted (a hover that
   * equals the page colour looks like a hole, not a highlight). */
  --surface-hover:          var(--neutral-50);

  /* WHERE YOU ARE, one answer for every navigation in the system: the sidebar,
   * the content side-panel rail and the chat history all paint the current place
   * with these three and nothing else.
   *
   * It used to be a NEUTRAL step — --accent in the sidebars, --muted here — and
   * that is the same step hover spends, so "you are here" and "your pointer is
   * here" said the identical thing. On the collapsed icon rail, where the label
   * is gone and only a disc is left, the current item stopped reading at all
   * (owner, 30.08: the active item does not register). The fix is not a bigger
   * grey: it is a DIFFERENT KIND of mark. The current place is the only tinted
   * thing on the rail — the soft brand surface, brand ink, and a hairline of the
   * brand around it — so it separates by hue and by edge, not by luminance
   * alone, which is what a small shape on a dark surface needs.
   *
   * Not the solid --primary disc it was before that: every product caps its logo
   * with one, so a saturated disc in the rail read as a second brand mark
   * (owner, 2026-08-24). Tinted and ringed is unmistakable and still quiet.
   *
   * Aliases, so a rebranded product gets its own colour for free. */
  --nav-active:                     var(--primary-soft);
  --nav-active-foreground:          var(--primary-accent);
  --nav-active-border:              var(--primary-accent);


  --destructive:            var(--danger-800);
  --destructive-foreground: var(--neutral-0);

  /* Status roles — components use these, never the success/warning/danger
   * primitive stops. Each tone: solid fill + on-fill text, a soft tint + its
   * text, and an emphasis tone for icons/accents. (danger == --destructive.) */
  --success:                     var(--success-800);
  --success-foreground:          var(--neutral-0);
  --success-soft:                var(--success-50);
  --success-soft-foreground:     var(--success-800);
  /* Ink, not fill: success-700 is 3.71:1 on white. success-800 is 5.25:1 and is
   * already what the solid fill uses, so the two read as the same green. */
  --success-emphasis:            var(--success-800);
  --warning:                     var(--warning-700);
  --warning-foreground:          var(--neutral-900);
  --warning-soft:                var(--warning-100);
  /* Dark ink on the yellow tint: warning-900 is a mid orange and only reached
   * 2.3:1 on warning-100. Matches --warning-foreground on the solid fill. */
  --warning-soft-foreground:     var(--neutral-900);
  /* The INK, not the fill. warning-700 is the bright yellow the solid badge is
   * filled with, and as text on white it sits at 1.54:1 — the `plain` warning
   * badge was effectively invisible. warning-950 is the dark amber the palette
   * already carried for exactly this, at 13.88:1. Found by axe in a real
   * browser; the token-level contrast check never tested this pair. */
  --warning-emphasis:            var(--warning-950);
  --destructive-soft:            var(--danger-50);
  --destructive-soft-foreground: var(--danger-900);
  /* Ink, not fill: danger-500 is 3.29:1 on white. danger-800 is 4.98:1, the same
   * stop --destructive already uses. */
  --destructive-emphasis:        var(--danger-800);
  /* Edge of a soft-tinted surface. A tint alone only reads on a surface it does
   * not match: an info notice on --muted, or a success notice on a pale card,
   * dissolved into the page. The border is what makes the shape survive any
   * background, so every tinted status surface carries one. Chosen per ramp by
   * eye, not by a fixed stop offset: the yellow ramp stays pale until 700, so
   * two stops up from the tint would be invisible there. */
  --success-border:              var(--success-300);
  --warning-border:              var(--warning-700);
  --destructive-border:          var(--danger-200);
  --primary-border:              var(--brand-200);

  --border:                 var(--neutral-200);
  --border-strong:          var(--neutral-300);   /* visible against --muted bg (sidebar rail, etc) */
  --input:                  var(--neutral-300);
  --ring:                   var(--brand-400);

  /* THE EDGE A CONTROL DRAWS SO ITS SHAPE SURVIVES ANY SURFACE.
   *
   * --surface-contrast answers "what do I fill myself with"; this answers "and
   * where do I end". They are two different questions, and the arithmetic says
   * so: no fill can be quiet enough to read as secondary AND separated enough
   * to clear 3:1 — solved numerically over the whole ramp, there is no such
   * colour. So the fill stays quiet and the edge carries the boundary. */
  --control-edge:           var(--neutral-550);


  /* Switch track when off — semantic so dark theme can override cleanly. */
  --switch-track-off:       var(--neutral-300);
  --switch-thumb:        var(--neutral-0);

  /* Avatar fallback (no image) — distinctive surface with foreground contrast. */
  --avatar:              var(--neutral-700);
  --avatar-foreground:      var(--neutral-0);

  --overlay:                rgb(0 0 0 / 0.4);   /* modal/drawer backdrop */
}

/* Dark theme — surface hierarchy. THE CARD IS DARKER THAN THE PAGE, which is the
 * reverse of the light theme, and both halves of that are deliberate.
 *
 *   page (bg + muted)  neutral-820 (#2c3036)  the lightest large area
 *   card               neutral-900 (#1f2328)  content sits in a well
 *   quiet fill         neutral-950 (#0e1217)  a control that must not dissolve
 *   edge / lift        neutral-800 (#3b3f45)  borders, hover, popover rows
 *
 * It used to follow the light theme's order — page deepest, card ~10% lighter,
 * "like GitHub/Linear/Notion" — and it did not work here: at 1.08:1 the step was
 * the same RATIO the light theme uses, and a ratio is not what the eye reads at
 * this end of the ramp. A whole page of cards came out as one grey wash (owner,
 * 30.08: the cards blend into the page). Every step is ~1.2:1 now, and the order is
 * inverted because two near-black surfaces separate far better when the darker
 * one is the smaller shape — a well reads, a slightly-brighter slab does not.
 *
 * The separation is bought by DARKENING THE CARD, not by lightening the page:
 * the first attempt raised the page to #363a3f and the theme stopped being dark
 * (owner, 30.08, hours later — the background should not be that light). The
 * page is back where it was and the well is dug under it.
 *
 * The stops themselves carry the numbers: styles/primitives.css. */
[data-theme="dark"] {
  color-scheme: dark;

  --background:             var(--neutral-820);
  --foreground:             var(--neutral-100);

  --card:                   var(--neutral-900);
  --card-foreground:        var(--neutral-100);

  /* The popover is a card that floats: the SAME surface as --card, exactly as in
   * the light theme where both are white. What lifts it is --shadow-popover and
   * its border, not a third grey — and it has to stay a step below the page, or
   * an open menu reads as a hole in the page rather than a sheet above it. */
  --popover:                var(--neutral-900);
  --popover-foreground:     var(--neutral-100);

  /* NOTE the direction: in dark the muted tint is LIGHTER than the card, where in
   * light it is darker than it. The role does not change — the surface a chip, a
   * track or a table head takes so it is not the card — but the value follows the
   * surface order of its own theme. */
  --muted:                  var(--neutral-820);   /* page surface — same as bg in dark */
  --muted-foreground:       var(--neutral-400);

  --primary:                var(--brand-400);     /* brand blue fill, same in both themes (white text on it) */
  --primary-foreground:     var(--neutral-0);     /* white on teal — brand-button consistency */
  --primary-hover:          var(--brand-500);     /* darker on hover, same direction as light */
  --primary-active:         var(--brand-600);
  --link-hover:             var(--brand-100);
  /* The brand as INK on dark. brand-300 clears the page and the muted surface
   * (4.58:1) but only reaches 2.84:1 on --accent — and --accent is where this
   * token actually lands most often: a dropdown item, a selected tree row, a
   * filter trigger. brand-200 clears all three (4.77:1 on accent). Measured
   * after axe in a real browser reported the filter trigger. */
  --primary-accent:         var(--brand-200);
  --primary-soft:           var(--brand-900);     /* deep tint readable in dark */
  --primary-soft-foreground: var(--brand-200);

  /* AI accent — lighter stop so violet stays legible on the dark surface. */
  --ai:                     var(--violet-400);
  --ai-foreground:          var(--neutral-900);
  --ai-soft:                var(--violet-900);
  --ai-soft-foreground:     var(--violet-200);

  --icon-muted:             var(--neutral-400);

  /* Charts — the same six hues restepped for the dark surface. */
  --chart-1: var(--series-1-dark);
  --chart-2: var(--series-2-dark);
  --chart-3: var(--series-3-dark);
  --chart-4: var(--series-4-dark);
  --chart-5: var(--series-5-dark);
  --chart-6: var(--series-6-dark);
  --chart-success: var(--success-500);
  --chart-warning: var(--warning-800);
  --chart-danger:  var(--danger-400);

  /* neutral-950, not -850: at -850 this token WAS --card, so every secondary
   * button standing on a card was 1.00:1 against it — the fill was not quiet, it
   * was absent. A step BELOW the card reads on the card and on the page both. */
  --secondary-foreground:   var(--neutral-100);

  --accent:                 var(--neutral-800);
  --accent-foreground:      var(--neutral-100);
  /* The nav's selected row. Defined per theme because the surface differs: on
   * the dark accent (#40444a) the brand fill sits at 1.39:1 and --primary-accent
   * at 2.84:1, both unreadable. brand-200 gives 4.77:1. Found by running axe in
   * a real browser — jsdom cannot evaluate contrast, so this had been invisible
   * to every check the repository had. */
  --nav-active-foreground:          var(--primary-accent);
  /* neutral-800, not -820: at -820 this was --popover, so every menu
   * highlight in this theme was the colour of the menu. */
  --accent-soft:            var(--neutral-800);   /* subtle hover on dark cards */
  --accent-strong:          var(--neutral-700);   /* the hover step past --accent */
  --accent-active:         var(--neutral-600);   /* one further: the pressed step, named `active` to match the `:active` selector that reads it */
  /* Row hover on a card: the page colour, a step ABOVE the card. In this theme
   * that is the highlight direction — the row rises towards the page rather than
   * sinking away from it. */
  --surface-hover:          var(--neutral-820);
  /* One step above the popover, which now sits at the card's own colour. The rule
   * this replaces is unchanged and is still what boundary-check enforces: a menu
   * highlight may never resolve to the colour of the menu. */
  --popover-hover:          var(--neutral-800);

  --destructive:            var(--danger-800);    /* danger-800: brand red deep enough for AA on white text (4.98:1) */
  --destructive-foreground: var(--neutral-0);

  /* Status roles — dark. Solid fills stay; soft tints go deep + light text. */
  --success:                     var(--success-800);
  --success-foreground:          var(--neutral-0);
  --success-soft:                var(--success-900);
  --success-soft-foreground:     var(--success-200);
  --success-emphasis:            var(--success-300);
  --warning:                     var(--warning-700);
  --warning-foreground:          var(--neutral-900);
  /* warning-930 and danger-930, not the -950 ink stops those two used to take.
   * Measured against the card, an ink stop as a TINT came to 1.05:1 and 1.11:1 —
   * the pill was not a pill, it was loose coloured text (owner, 30.08: the toned ones
   * look plain strange). The two new stops sit at the luminance of
   * --success-900, the one tone that always read, so all four tint by the same
   * amount now. */
  --warning-soft:                var(--warning-930);
  --warning-soft-foreground:     var(--warning-200);
  --warning-emphasis:            var(--warning-300);
  --destructive-soft:            var(--danger-930);
  --destructive-soft-foreground: var(--danger-100);
  /* danger-200, not -300: the page is a lighter grey in this theme now, and the
   * red ink that cleared the old one measured 4.17:1 on it and 2.95:1 on its own
   * tint. One stop lighter clears both. */
  --destructive-emphasis:        var(--danger-200);
  /* Dark edges go LIGHTER than the deep tint, the mirror of the light theme. */
  --success-border:              var(--success-700);
  --warning-border:              var(--warning-900);
  --destructive-border:          var(--danger-800);
  --primary-border:              var(--brand-700);

  --border:                 var(--neutral-800);   /* uniform subtle borders */
  --border-strong:          var(--neutral-700);   /* sidebar rail, more visible on dark muted */
  --input:                  var(--neutral-800);   /* same as --border for visual consistency */
  --ring:                   var(--brand-300);   /* lighter so the focus outline reads on dark */

  --control-edge:           var(--neutral-550);


  --switch-track-off:       var(--neutral-800);
  --switch-thumb:        var(--neutral-100);

  --avatar:              var(--neutral-700);
  --avatar-foreground:      var(--neutral-100);

  --overlay:                rgb(0 0 0 / 0.6);   /* stronger overlay on dark */

  /* Shadows — black-on-dark needs much higher opacity to register. */
  --shadow-sm:        0 1px 2px rgb(0 0 0 / 0.35);
  --shadow-md:        0 4px 12px rgb(0 0 0 / 0.40);
  --shadow-lg:        0 12px 32px rgb(0 0 0 / 0.50);
  --shadow-popover:   0 4px 24px rgb(0 0 0 / 0.40);
  --shadow-card-hover: 0 6px 20px rgb(0 0 0 / 0.45);
}

[data-theme="light"] { color-scheme: light; }

/* Light-lock: render this subtree light regardless of the app theme. Tokens come
 * from the shared `:root` block above; here we pin the appearance and restore the
 * light shadow set (the dark block overrode --shadow-* on <html>, which would
 * otherwise inherit in). Mirrors the light values in primitives.css / settings.css. */
[data-theme-lock="light"] {
  color-scheme: light;
  --shadow-sm: 0 1px 2px rgb(0 0 0 / 0.08);
  --shadow-md: 0 2px 16px rgb(0 0 0 / 0.06);
  --shadow-lg: 0 12px 32px rgb(0 0 0 / 0.14);
  --shadow-popover: 0 4px 24px rgb(0 0 0 / 0.08);
  --shadow-card-hover: 0 6px 20px rgb(0 0 0 / 0.12);
}

/* System mode: respect OS preference when no explicit data-theme is set. */
/* The SECOND dark definition: the one that applies when the visitor has chosen
 * no theme and the OS says dark. It has to repeat the block above, and on
 * 2026-07-31 five tokens had drifted apart — `--warning-soft` and
 * `--destructive-soft` pointed at a mid stop here and a deep one there, and
 * three tokens added later were missing entirely. The rendered page uses THIS
 * block, so the drifted values were the ones people saw while
 * `npm run contrast` measured the other block and reported green.
 *
 * The contrast check now reads both, so they cannot drift again silently. */
/* jscpd:ignore-start
 * This block is a DELIBERATE mirror of [data-theme="dark"] above, and the file
 * says why: a media query cannot join a selector list, so "the user chose dark"
 * and "the user chose nothing and the OS says dark" have to be written twice.
 * The duplication is the point — `npm run contrast` reads BOTH blocks precisely
 * because they drifted once. Excluded here rather than raising the package-wide
 * clone threshold, which would have hidden real copy-paste everywhere else.
 * The proper fix is to generate this block from the one above, the way tokens/
 * is generated from styles/; until then the contrast gate is what holds it. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;

    --background:             var(--neutral-820);
    --foreground:             var(--neutral-100);
    --card:                   var(--neutral-900);
    --card-foreground:        var(--neutral-100);
    --popover:                var(--neutral-900);
    --popover-foreground:     var(--neutral-100);
    --muted:                  var(--neutral-820);
    --muted-foreground:       var(--neutral-400);
    --primary:                var(--brand-400);
    --primary-foreground:     var(--neutral-0);
    --primary-hover:          var(--brand-500);
    --primary-active:         var(--brand-600);
    --link-hover:             var(--brand-100);
    --primary-accent:         var(--brand-200);
    --primary-soft:           var(--brand-900);
    --primary-soft-foreground: var(--brand-200);
    --nav-active-foreground:          var(--primary-accent);
    --ai:                     var(--violet-400);
    --ai-foreground:          var(--neutral-900);
    --ai-soft:                var(--violet-900);
    --ai-soft-foreground:     var(--violet-200);
    --icon-muted:             var(--neutral-400);

    /* Charts — the same six hues restepped for the dark surface. */
    --chart-1: var(--series-1-dark);
    --chart-2: var(--series-2-dark);
    --chart-3: var(--series-3-dark);
    --chart-4: var(--series-4-dark);
    --chart-5: var(--series-5-dark);
    --chart-6: var(--series-6-dark);
  --chart-success: var(--success-500);
    --chart-warning: var(--warning-800);
    --chart-danger:  var(--danger-400);
    --secondary-foreground:   var(--neutral-100);
    --accent:                 var(--neutral-800);
    --accent-foreground:      var(--neutral-100);
    --accent-soft:            var(--neutral-800);
    --accent-strong:          var(--neutral-700);
    --accent-active:         var(--neutral-600);
    --popover-hover:          var(--neutral-800);
    --surface-hover:          var(--neutral-820);
    --destructive:            var(--danger-800);
    --destructive-foreground: var(--neutral-0);
    --success:                     var(--success-800);
    --success-foreground:          var(--neutral-0);
    --success-soft:                var(--success-900);
    --success-soft-foreground:     var(--success-200);
    --success-emphasis:            var(--success-300);
    --warning:                     var(--warning-700);
    --warning-foreground:          var(--neutral-900);
    --warning-soft:                var(--warning-930);
    --warning-soft-foreground:     var(--warning-200);
    --warning-emphasis:            var(--warning-300);
    --destructive-soft:            var(--danger-930);
    --destructive-soft-foreground: var(--danger-100);
    --destructive-emphasis:        var(--danger-200);
    --success-border:              var(--success-700);
    --warning-border:              var(--warning-900);
    --destructive-border:          var(--danger-800);
    --primary-border:              var(--brand-700);
    --border:                 var(--neutral-800);
    --border-strong:          var(--neutral-700);
    --input:                  var(--neutral-800);
    --ring:                   var(--brand-300);
    --control-edge:           var(--neutral-550);
    --switch-track-off:       var(--neutral-800);
    --switch-thumb:        var(--neutral-100);
    --avatar:              var(--neutral-700);
    --avatar-foreground:      var(--neutral-100);
    --overlay:                rgb(0 0 0 / 0.6);
    --shadow-sm:        0 1px 2px rgb(0 0 0 / 0.35);
    --shadow-md:        0 4px 12px rgb(0 0 0 / 0.40);
    --shadow-lg:        0 12px 32px rgb(0 0 0 / 0.50);
    --shadow-popover:   0 4px 24px rgb(0 0 0 / 0.40);
    --shadow-card-hover: 0 6px 20px rgb(0 0 0 / 0.45);
  }
}
/* jscpd:ignore-end */

/* UTILITIES — the few cross-cutting behaviours that are not worth a component.
 *
 * A component earns a folder, a golden example, a registry entry and ~280 tokens
 * of context on every future task. A fifteen-line animation does not: it earns a
 * class. Keep this file small, and prefer a component the moment something needs
 * props, state or markup of its own.
 *
 * Loaded by index.css, so every app that consumes the design system has it. */

/* Live-status pulse — "this is happening right now": a recording dot, a live
 * call marker, an active session. Eight separate @keyframes for this existed
 * across the products before it moved here, all doing the same fade.
 *
 * Tune per use through the two custom properties rather than redefining it:
 *   .my-dot { --pulse-duration: 2s; --pulse-dim: 0.5; }
 */
.pulse {
  animation: pulse var(--pulse-duration, 1.2s) ease-in-out infinite;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: var(--pulse-dim, 0.3);
  }
}

/* Ecosystem symbol — the documented CONTRACT behind each product's mark, moved
 * here the day the third app drew one (the closing condition recorded in the
 * promotion scout). The drawing is the whole point and must differ per app
 * (a waveform, a chat condensing, a
 * bell), so no component: each app keeps its own <svg class="eco-symbol">.
 * What repeats is the contract — a 48x48 viewBox with an even ~7px safe area,
 * strokes in the brand gradient (var(--primary-accent) → var(--primary)), no
 * background tile, and any animation stops here under reduced motion. */
.eco-symbol {
  display: block;
}
@media (prefers-reduced-motion: reduce) {
  .eco-symbol * {
    animation: none;
  }
}

/* Visually hidden, still read aloud. For the text that carries a meaning the
 * layout carries visually: a live region confirming a copy, the "+3 more" behind
 * an avatar stack. Not `display: none` — that removes it from the accessibility
 * tree too, which is the opposite of the point. */
/* Pinned, not left at its static position.
 *
 * With `inset: auto` an absolutely positioned element stays where it would have
 * been in flow, and its containing block is the nearest positioned ancestor —
 * the PAGE, when there is none. Deep inside a pane that scrolls, that static
 * position is far below the fold, so a 1px hidden span stretched the document
 * past the shell and left a strip of body colour under the page (measured
 * 2026-08-24: 184px on a laptop, 364px on a short one, on a screen whose only
 * offender was <CopyButton>'s live region).
 *
 * Nine of the ten components that hide text this way have no positioned root,
 * so positioning each of them would be nine chances to forget the tenth.
 * Pinning here fixes all of them and cannot be forgotten. */
.sr-only {
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 0;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ── The railless shell — the contract a no-rail app owes its pages ──────────
 *
 * Promoted 2026-08-21 from two products, the second of them the no-rail
 * app being the trigger the scout recorded. A CONTRACT here rather than a
 * component on purpose: one of them places its <main> per route (AuthTemplate
 * brings its own, and a second one is a duplicate landmark), so a shell that
 * renders <main> for you cannot serve it — and the two apps genuinely differ
 * on --page-max-width, which therefore stays per app, set in its own CSS.
 *
 * What IS one contract, restated twice until now:
 *   - the muted page surface (white cards read on it; --background is the
 *     CARD colour) on a flex column that fills the viewport;
 *   - the height release for a panelled page, same rule AppLayout carries:
 *     two nested scrollers, one of them the document, mean the inner column
 *     only starts moving once the outer has run out — the opposite of the
 *     intent. Keyed on the page's own opt-in ([data-panels]);
 *   - the shared PageHeader capped and centred to the content column, scoped
 *     for specificity over the bare .page-header rule so the winner does not
 *     depend on which stylesheet the bundler emitted second. Transparent,
 *     because a welcome screen that does not scroll reads an opaque bar as a
 *     grey band cut across the wash. */
.app-bare {
  min-block-size: 100dvh;
  display: flex;
  flex-direction: column;
  background: var(--muted);
  color: var(--foreground);
}

.app-bare-main {
  flex: 1;
  min-inline-size: 0;
  display: flex;
  flex-direction: column;
  padding-block-start: var(--space-4);
}

@media (min-width: 62rem) {
  .app-bare:has([data-panels]) {
    block-size: 100dvh;
    overflow: hidden;
  }

  .app-bare:has([data-panels]) .app-bare-main {
    min-block-size: 0;
  }
}

.app-bare .page-header {
  inline-size: 100%;
  max-inline-size: var(--page-max-width);
  margin-inline: auto;
  background: transparent;
}

/* ── A RAISED SURFACE ──────────────────────────────────────────────────────
 * An element that other things sit ON, rather than one that sits on something.
 * Note the direction: `data-surface` is the OTHER question — what a control is
 * standing on — and it is already a declared word meaning exactly that, so this
 * one could not borrow it (vocabulary, 2026-08-26).
 *
 * A raised surface is white in light and near-black in dark, so a quiet control
 * placed on it has to contrast the OTHER WAY: on the grey page it goes white,
 * here it goes grey. Those three tokens are how `--surface-contrast` answers
 * "what does a quiet thing fill itself with so it does not dissolve".
 *
 * This was declared in eleven stylesheets, with the same explanatory comment
 * copied word for word into nine of them. Eleven copies of one decision is
 * eleven places to forget it — and a twelfth surface added tomorrow would have
 * had to know to copy it. Now it declares one attribute.
 *
 *   card     the surface is --card: a Card, a SidePanel, a ChatShell
 *   popover  the surface is --popover: a menu, a dialog, a toast — and a row
 *            inside it hovers against THAT surface, not against the page
 *   tint     the surface is a TONE tint: an Alert. See below — it is the one
 *            surface that cannot answer the question with a fill.
 */
[data-raised] {
  --surface-contrast: var(--accent);
  --surface-contrast-hover: var(--accent-strong);
  --surface-contrast-active: var(--accent-active);
}

/* A TINT IS A THIRD SURFACE, and it was being answered as if it were the second.
 *
 * The rule above has two cases because it was written for two: the grey page,
 * where a quiet control goes white, and the white card, where it goes grey. An
 * Alert declared itself a card and is not one — its background is
 * --primary-soft / --warning-soft / --success-soft / --destructive-soft, a pale
 * tint, and --accent on a pale tint is not a contrast, it is a colour match.
 * Measured on a warm-accent brand palette: 1.04:1 on the info tint, 1.01 on
 * danger, 1.02 on success. That is the exact failure --surface-contrast was invented to fix,
 * one surface further on (owner, 31.08, pointing at an alert's action: look at
 * how this button looks). It also lands COOL on a warm tint, which is why it
 * reads as disabled rather than merely as flat.
 *
 * A tint cannot be answered by a fill at all, and that is not a shortcoming of
 * the token — a pale tint IS nearly white, so no light fill can be far from it:
 * --card only reaches 1.06 to 1.13. So the tint is the one surface where a quiet
 * control separates by ELEVATION. Not by a line: a boundary round a button was
 * argued against twice (2026-08-22, 08-23) and nothing about that has changed.
 * A shadow is a different claim — it says the control sits ON the tint rather
 * than drawing an edge around it — and it costs nothing in dark, where the
 * near-black fill already separates (1.32 to 2.18) and the shadow is invisible.
 *
 * The shadow travels as a TOKEN so the Button reads its own surface, rather than
 * the Alert reaching into the Button. Every other surface leaves it unset, and
 * the fallback in the `var()` is `none`. */
[data-raised='tint'] {
  --surface-contrast: var(--card);
  --surface-contrast-hover: var(--accent);
  --surface-contrast-active: var(--accent-strong);
  --surface-contrast-shadow: var(--shadow-sm);
}

[data-raised='popover'] {
  --surface-hover: var(--popover-hover);
}

import { createContext, useCallback, use, useEffect, useMemo, useRef, useState, type ReactNode } from 'react'

/* Sidebar has TWO independent dimensions of state:
 *   - collapsed (desktop): icon-only rail vs. full-width
 *   - mobileOpen (small screens): drawer hidden vs. overlayed
 * Desktop state is persisted; mobile state is ephemeral (closes on nav). */

type SidebarContextValue = {
  collapsed: boolean
  toggleCollapsed: () => void
  mobileOpen: boolean
  openMobile: () => void
  closeMobile: () => void
}

/* Exported so <AppLayout> can PROVIDE this value itself, bridged to its own
   navOpen/onNavClose. Without that the shell and the button it ships were two
   halves of one mechanism with nothing between them — see the note in
   AppLayout.tsx. */
export const SidebarContext = createContext<SidebarContextValue | null>(null)
export type { SidebarContextValue }
const STORAGE_KEY = 'sidebar.collapsed'

function readPersisted(): boolean {
  return localStorage.getItem(STORAGE_KEY) === '1'
}

export function SidebarProvider({ children }: { children: ReactNode }) {
  const [collapsed, setCollapsed] = useState<boolean>(readPersisted)
  const [mobileOpen, setMobileOpen] = useState(false)
  const isFirstRunRef = useRef(true)

  useEffect(() => {
    /* Skip first-run write — initial value was just read from localStorage. */
    if (isFirstRunRef.current) { isFirstRunRef.current = false; return }
    localStorage.setItem(STORAGE_KEY, collapsed ? '1' : '0')
  }, [collapsed])

  const toggleCollapsed = useCallback(() => setCollapsed((v) => !v), [])
  const openMobile  = useCallback(() => setMobileOpen(true), [])
  const closeMobile = useCallback(() => setMobileOpen(false), [])

  const value = useMemo(
    () => ({ collapsed, toggleCollapsed, mobileOpen, openMobile, closeMobile }),
    [collapsed, toggleCollapsed, mobileOpen, openMobile, closeMobile],
  )

  return (
    <SidebarContext value={value}>
      {children}
    </SidebarContext>
  )
}

export function useSidebar() {
  const ctx = use(SidebarContext)
  if (!ctx) throw new Error('useSidebar must be used within SidebarProvider')
  return ctx
}

/**
 * The same context, but null outside a provider instead of throwing.
 *
 * For components that live BOTH inside an app shell and on their own: PageHeader
 * renders the mobile menu button when there is a drawer to open, and renders
 * nothing extra in the visual gallery or a golden example, where there is no
 * sidebar at all. Throwing there would make the component unrenderable outside
 * an app, which is exactly what a design system must not require.
 */
export function useSidebarOptional() {
  return use(SidebarContext)
}

/* The arithmetic every chart in this system shares.
 *
 * It lives here and not in a component because two charts that compute their
 * scale differently draw the same numbers at two heights, and a reader compares
 * them anyway. One scale, one set of ticks, one rounding rule. */

/** A "nice" step: 1, 2, 5 or 10 times a power of ten. What a person would have
 *  picked — 0/25/50/75/100, never 0/23/46/69/92. */
function niceStep(rough: number): number {
  const power = 10 ** Math.floor(Math.log10(rough))
  const scaled = rough / power
  const step = scaled <= 1 ? 1 : scaled <= 2 ? 2 : scaled <= 5 ? 5 : 10
  return step * power
}

export type Scale = {
  /** Top of the axis: the first nice number at or above the data. */
  max: number
  /** The values to draw a grid line and a label at, bottom to top. */
  ticks: number[]
  /** Where a value sits on the axis, 0 (floor) to 1 (top). */
  at: (value: number) => number
}

/**
 * The axis for a set of values. `count` is a TARGET number of gaps, not a
 * promise: the step is rounded to a nice number first, because a readable
 * scale matters more than an exact tick count.
 *
 * The floor is always zero. A bar chart that starts anywhere else lies about
 * the ratio between its bars, and that is the single most common way a chart
 * misleads without saying anything false.
 */
export function scaleFor(values: number[], count = 4): Scale {
  const peak = Math.max(0, ...values)
  if (peak === 0) return { max: 1, ticks: [0, 1], at: () => 0 }
  const step = niceStep(peak / count)
  const max = Math.ceil(peak / step) * step
  const ticks: number[] = []
  for (let t = 0; t <= max + step / 2; t += step) ticks.push(Number(t.toFixed(10)))
  return { max, ticks, at: (v) => Math.max(0, Math.min(1, v / max)) }
}

/** Thousands separated, decimals kept only when the number has them. Charts
 *  print a lot of numbers and they all have to line up. */
export function formatValue(value: number, locale?: string): string {
  return new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }).format(value)
}

/** The path through a series of points, as an SVG `d`. */
export function linePath(points: readonly (readonly [number, number])[]): string {
  return points.map(([x, y], i) => `${i ? 'L' : 'M'}${x.toFixed(2)} ${y.toFixed(2)}`).join(' ')
}

/** The same path closed down to a baseline, for the area under a line. */
export function areaPath(points: readonly (readonly [number, number])[], baseline: number): string {
  if (!points.length) return ''
  const first = points[0]
  const last = points[points.length - 1]
  return `${linePath(points)} L${last[0].toFixed(2)} ${baseline} L${first[0].toFixed(2)} ${baseline} Z`
}

/* Joins class names and drops the falsy ones — the one utility every component
 * in this package calls, 111 of them. It exists so a conditional class is
 * written the same way everywhere: `cn('card', open && 'is-open')` rather than
 * a template string per component, which is how a stray `undefined` reaches the
 * DOM as a class name. Reach for it whenever a class depends on a prop.
 *
 * @internal Plumbing rather than a choice: it is called by whatever needs it and
 * nobody reaches for it on purpose, so it stays out of the index an agent reads
 * on every task. (2026-09-03)
 */
export function cn(...classes: (string | false | null | undefined)[]): string {
  return classes.filter(Boolean).join(' ')
}

import { type Ref } from 'react'

/**
 * Fill our own ref AND whatever ref the caller already put on the element.
 *
 * `<Tooltip>` and `<HoverCard>` both inject handlers into their child with
 * `cloneElement`, which replaces the child's `ref`. Without composing, wrapping
 * an element in a Tooltip would silently break any ref the caller had on it, and
 * silently is the operative word: nothing type-checks it and nothing renders
 * differently. Both components had the same fifteen lines; this is them, once.
 *
 * React calls the returned callback during commit, never during render, so the
 * writes below are not render-phase mutation even though the compiler cannot
 * prove it from the call site.
 */
export function composeRefs<T>(...refs: (Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === 'function') ref(node)
      /* Writing into the caller's own ref object is what forwarding a ref MEANS,
       * and taking it as a typed `Ref<T>` parameter rather than digging it out of
       * `children.props` is what makes that legible to the compiler too: inline in
       * the components it read as mutating a prop, here it plainly is not. */
      else if (ref && typeof ref === 'object') ref.current = node
    }
  }
}

import { createContext, use } from 'react'

/* Shared between FilterBar (organism) and FilterDropdown (molecule) without
 * an upward atomic import — both depend on this neutral lib module instead.
 * `inSheet` lets FilterDropdown render select-style + full-width menu inside
 * the mobile FilterBar modal.
 *
 * @internal Plumbing rather than a choice: the two parts that share it reach for
 * each other, not for this, so it stays out of the index an agent reads on every
 * task. (2026-09-03)
 */
export const FilterBarContext = createContext<{ inSheet: boolean }>({ inSheet: false })

export function useFilterBar() {
  return use(FilterBarContext)
}

/* Where the menu goes. Pure arithmetic, deliberately separated from the
 * component.
 *
 * Why it lives here instead of inline: jsdom has no layout engine, so every
 * getBoundingClientRect() in a test returns zeros and the whole placement branch
 * runs on nothing. Mutation testing made that visible — 60 of the 139 surviving
 * mutants in Dropdown.tsx sat on these lines, meaning the flip-above, the
 * edge-pinning and the RTL mirror were not verified by anything. Taking the
 * measurements as arguments makes them testable without a browser. */

/* THE ONE READ OF THE DOCUMENT'S DIRECTION.
 *
 * Three layers asked `document.documentElement.dir === 'rtl'` for themselves,
 * which is three chances to ask a slightly different question — and the whole
 * reason this file exists is that geometry answered inline is geometry nobody
 * tests. It lives here rather than in a component because every caller is about
 * to hand the answer to computePlacement below. (2026-09-03) */
export const isRtl = () => document.documentElement.dir === 'rtl'

export const MENU_MARGIN = 4
export const EDGE_PAD = 8

export interface Box {
  top: number
  bottom: number
  left: number
  right: number
  width: number
  /* Carried because a layer that sits BESIDE its trigger centres on it, and
   * bottom - top is the caller doing arithmetic the reader already did.
   * (2026-09-03, when <Tooltip> joined the shared read.) */
  height: number
}

export interface PlacementInput {
  /** The trigger, in viewport coordinates. */
  trigger: Box
  /** The menu's NATURAL size (scrollHeight/scrollWidth, before any clamp). */
  menu: { height: number; width: number }
  viewport: { width: number; height: number }
  align: 'start' | 'end'
  isRtl: boolean
  matchTriggerWidth?: boolean | 'min'
  /* Which side the caller WANTS. A menu wants below and flips up when it has to;
   * a popover may be asked for above. Either way the flip rule underneath is the
   * same one — go to the other side only when this one does not fit and the
   * other genuinely has more room — which is why the preference is an input here
   * rather than a second copy of the arithmetic in a component. (2026-09-03) */
  prefer?: 'below' | 'above'
}

export interface Placement {
  top: number
  left?: number
  right?: number
  maxHeight: number
  width?: number
  minWidth?: number
}

/** Does the menu have to open upwards? Only when it does not fit below AND there
 *  is genuinely more room above — otherwise flipping just moves the problem. */
export function placeAbove(input: Pick<PlacementInput, 'trigger' | 'menu' | 'viewport' | 'prefer'>): boolean {
  const { spaceAbove, spaceBelow } = freeSpace(input)
  if (input.prefer === 'above') return !(input.menu.height > spaceAbove && spaceBelow > spaceAbove)
  return input.menu.height > spaceBelow && spaceAbove > spaceBelow
}

function freeSpace({ trigger, viewport }: Pick<PlacementInput, 'trigger' | 'viewport'>) {
  return {
    spaceBelow: viewport.height - trigger.bottom - EDGE_PAD,
    spaceAbove: trigger.top - EDGE_PAD,
  }
}

/** Which edge the menu hangs from. Starts from the requested alignment (mirrored
 *  in RTL) and flips only when that side would run off the viewport. A menu of
 *  unknown width (0, not measured yet) never flips: guessing would make the menu
 *  jump on the frame after it mounts. */
export function pinsRight(input: Pick<PlacementInput, 'trigger' | 'menu' | 'viewport' | 'align' | 'isRtl'>): boolean {
  const { trigger, menu, viewport, align, isRtl } = input
  const wanted = align === 'end' ? !isRtl : isRtl
  if (menu.width <= 0) return wanted
  if (wanted) return trigger.right - menu.width >= EDGE_PAD
  return trigger.left + menu.width > viewport.width - EDGE_PAD
}

/** The final inline position for the menu. */
export function computePlacement(input: PlacementInput): Placement {
  const { trigger, menu, viewport, matchTriggerWidth } = input
  const above = placeAbove(input)
  const { spaceAbove, spaceBelow } = freeSpace(input)

  const top = above
    ? Math.max(EDGE_PAD, trigger.top - menu.height - MENU_MARGIN)
    : trigger.bottom + MENU_MARGIN
  const maxHeight = (above ? spaceAbove : spaceBelow) - MENU_MARGIN

  const width = matchTriggerWidth === true ? trigger.width : undefined
  const minWidth = matchTriggerWidth === 'min' ? trigger.width : undefined

  return pinsRight(input)
    ? { top, right: Math.max(EDGE_PAD, viewport.width - trigger.right), maxHeight, width, minWidth }
    : { top, left: Math.max(EDGE_PAD, trigger.left), maxHeight, width, minWidth }
}

/* READING THE PAGE, once, for everybody who anchors something to something.
 *
 * The arithmetic above takes numbers so it can be tested without a browser, and
 * that split is right — but it left every caller doing the same three DOM reads
 * by hand: the trigger's rect, the layer's size, the viewport. Four parts did,
 * and lint:mechanism reported them as one behaviour written four times for as
 * long as it has existed. This is that half, in one place.
 *
 * `natural` is the one real difference between the callers and it stays visible
 * as a flag rather than as four silent choices: a menu that clamps its own
 * height has to be measured by scrollHeight, because offsetHeight is the size
 * AFTER the clamp and reads as "it fits" for ever. A layer that does not clamp
 * is measured as rendered. (2026-09-03) */
export function readAnchor(
  trigger: Element | null,
  layer: { scrollHeight: number; scrollWidth: number; offsetHeight: number; offsetWidth: number } | null,
  { natural = false } = {},
): Pick<PlacementInput, 'trigger' | 'menu' | 'viewport' | 'isRtl'> | null {
  if (!trigger) return null
  const r = trigger.getBoundingClientRect()
  return {
    trigger: { top: r.top, bottom: r.bottom, left: r.left, right: r.right, width: r.width, height: r.height },
    menu: natural
      ? { height: layer?.scrollHeight ?? 0, width: layer?.scrollWidth ?? 0 }
      : { height: layer?.offsetHeight ?? 0, width: layer?.offsetWidth ?? 0 },
    viewport: { width: window.innerWidth, height: window.innerHeight },
    isRtl: isRtl(),
  }
}

/* Dates, said the way a person reading a chat would say them.
 *
 * Promoted out of one app when a second needed the same five helpers: a chat
 * tool says "12 min ago" and groups a thread by day, and two products doing it from copies is the
 * thing the promotion rule exists to stop. */

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/**
 * "just now" / "12 min ago" / "3 h ago" / "yesterday" / a date.
 *
 * `now` is a parameter rather than read inside, so the tests are not about what time it is.
 */
export function ago(iso: string | null | undefined, now: number = Date.now()): string {
  if (!iso) return "never";
  const then = Date.parse(iso);
  if (Number.isNaN(then)) return "never";
  const diff = now - then;
  if (diff < 0) return "just now";
  if (diff < MINUTE) return "just now";
  if (diff < HOUR) return `${Math.floor(diff / MINUTE)} min ago`;
  if (diff < DAY) return `${Math.floor(diff / HOUR)} h ago`;
  if (diff < 2 * DAY) return "yesterday";
  if (diff < 7 * DAY) return `${Math.floor(diff / DAY)} days ago`;
  return new Date(then).toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
}

/** The clock time on a message, which is what a thread is read by. */
export function timeOfDay(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
}

/** The day a message belongs to, for the separators between days in a thread. */
export function dayLabel(iso: string, now: number = Date.now()): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  const startOf = (t: number) => new Date(new Date(t).setHours(0, 0, 0, 0)).getTime();
  const days = Math.round((startOf(now) - startOf(d.getTime())) / DAY);
  if (days === 0) return "Today";
  if (days === 1) return "Yesterday";
  return d.toLocaleDateString(undefined, { weekday: "short", day: "numeric", month: "short" });
}

/** "1 message" / "14 messages", because "14 message(s)" is not English. */
export function plural(n: number, one: string, many: string = `${one}s`): string {
  return `${n} ${n === 1 ? one : many}`;
}

/**
 * A thread split into days, in the order it arrived.
 *
 * Anyone catching up reads a chat as "what happened yesterday", not "the last 43 messages", so the
 * day is the unit the screen is grouped by. Consecutive runs only: the input is already ordered,
 * and grouping by key instead would silently reorder a thread whose clocks disagree.
 *
 * @public Nothing in this package calls it: a consuming app does, through `@lib/relativeTime`.
 * Without the tag the dead-export rule is right about what it can see and wrong about the
 * repository, which is why it reads the consuming apps when they are on disk.
 */
export function byDay<T extends { at: string }>(items: T[], now: number = Date.now()): { day: string; items: T[] }[] {
  const out: { day: string; items: T[] }[] = [];
  for (const item of items) {
    const day = dayLabel(item.at, now);
    const last = out[out.length - 1];
    if (last?.day === day) last.items.push(item);
    else out.push({ day, items: [item] });
  }
  return out;
}

/**
 * The same idea as `ago`, said in the reader's language.
 *
 * Both live here on purpose rather than one calling the other. `ago` returns
 * fixed English strings ("12 min ago", "yesterday") that two chat products and
 * their tests depend on word for word; this one hands the wording to
 * `Intl.RelativeTimeFormat`, which is what a component shipped in en AND ar has
 * to do. Changing `ago` to match would rewrite copy in two shipped products.
 *
 * `now` is a parameter for the same reason it is one above: so a test is not
 * about what time it is.
 */
export function relativeLabel(ts: number, now: number, locale?: string): string {
  const diff = ts - now;
  const abs = Math.abs(diff);
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  const WEEK = 7 * DAY;
  const MONTH = 30 * DAY;
  const YEAR = 365 * DAY;
  if (abs < MINUTE) return rtf.format(Math.round(diff / 1000), "second");
  if (abs < HOUR) return rtf.format(Math.round(diff / MINUTE), "minute");
  if (abs < DAY) return rtf.format(Math.round(diff / HOUR), "hour");
  if (abs < WEEK) return rtf.format(Math.round(diff / DAY), "day");
  if (abs < MONTH) return rtf.format(Math.round(diff / WEEK), "week");
  if (abs < YEAR) return rtf.format(Math.round(diff / MONTH), "month");
  return rtf.format(Math.round(diff / YEAR), "year");
}

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react'
import { useDismiss } from './useDismiss'
import { useLatest } from './useLatest'

/**
 * THE FLOATING-LAYER MECHANISM: a layer anchored to a trigger, kept in place
 * while the page moves, and dismissed the two ways every such layer is.
 *
 * It exists because <Dropdown> and <Popover> each wrote it, and writing it
 * twice is how the two drifted (2026-08-26): Dropdown throttled its reflow with
 * requestAnimationFrame and listened passively, Popover repositioned
 * synchronously on every scroll event. One of the two was simply worse and
 * nothing said so — which is the failure mode a shared mechanism prevents and a
 * shared *component* would not have, since these two are not one component.
 *
 * GEOMETRY IS NOT HERE. The caller passes `measure`, because where a menu wants
 * to sit and where a dialog wants to sit are different questions; the listeners,
 * the throttling, the mount timing and the dismissal are the same question.
 * `lib/placement.ts` is the arithmetic, shared and tested separately.
 */
export function useAnchoredLayer<P>({
  open,
  onClose,
  measure,
  dismissible = true,
}: {
  open: boolean
  /** Called on an outside press or Escape. Ignored when `dismissible` is false. */
  onClose: () => void
  /** Where the layer goes, in viewport coordinates. Read the refs below. */
  measure: () => P | null
  dismissible?: boolean
}) {
  const triggerRef = useRef<HTMLElement | null>(null)
  const layerRef = useRef<HTMLElement | null>(null)
  const [position, setPosition] = useState<P | null>(null)
  /* The layer is portalled and mounts a tick after `open`, so its real size does
   * not exist yet on the first pass. A mount flag re-runs the measurement once
   * it does; a ref callback alone would re-run on every render and loop. */
  const [mounted, setMounted] = useState(false)

  const measureRef = useLatest(measure)

  const setLayer = useCallback((node: HTMLElement | null) => {
    layerRef.current = node
    setMounted(Boolean(node))
  }, [])

  useLayoutEffect(() => {
    if (!open) return
    // eslint-disable-next-line @eslint-react/set-state-in-effect -- positions a portal from measured geometry; not derivable during render
    setPosition(measureRef.current())
  }, [open, mounted, measureRef])

  /* Reflow while open: rAF-throttled and passive, so a scroll stays a scroll. */
  useEffect(() => {
    if (!open) return
    let raf = 0
    const update = () => {
      cancelAnimationFrame(raf)
      raf = requestAnimationFrame(() => setPosition(measureRef.current()))
    }
    window.addEventListener('scroll', update, { capture: true, passive: true })
    window.addEventListener('resize', update, { passive: true })
    return () => {
      cancelAnimationFrame(raf)
      window.removeEventListener('scroll', update, true)
      window.removeEventListener('resize', update)
    }
  }, [open, measureRef])

  /* The two dismissals are `useDismiss`'s: <ContextMenu> needs them without any
     of the measuring above, so they are their own hook. */
  useDismiss({ open: open && dismissible, onClose, stays: [triggerRef, layerRef] })

  /* `mounted` is returned because a caller may have its own work that can only
     run once the layer's DOM exists — Dropdown caches its menu items and moves
     focus to the first one. */
  return { triggerRef, layerRef, setLayer, position, mounted }
}

import { useEffect, type RefObject } from 'react'
import { useLatest } from './useLatest'

/**
 * THE TWO DISMISSALS every transient layer answers to: a press outside it, and
 * Escape. Nothing else — a layer that also closes on scroll, on blur or on a
 * route change is describing its own lifecycle, and that belongs to it.
 *
 * Separated from `useAnchoredLayer` because <ContextMenu> needs exactly this
 * and none of the rest: its position comes from the pointer event that opened
 * it, so there is nothing to measure and nothing to reflow. Passing it a
 * `measure` that returns a stored point would be a no-op pretending to be a
 * measurement (2026-08-26). Sharing this much and no more is the honest amount.
 *
 * `stays` are the elements a press inside must NOT close: the layer itself, and
 * usually the trigger, whose own click handler already toggles it.
 */
export function useDismiss({
  open,
  onClose,
  stays,
}: {
  open: boolean
  onClose: () => void
  stays: RefObject<HTMLElement | null>[]
}) {
  const onCloseRef = useLatest(onClose)
  const staysRef = useLatest(stays)

  useEffect(() => {
    if (!open) return
    const inside = (target: Node) =>
      staysRef.current.some((r) => r.current?.contains(target))
    const onDown = (e: globalThis.MouseEvent) => {
      if (inside(e.target as Node)) return
      onCloseRef.current()
    }
    const onKey = (e: globalThis.KeyboardEvent) => {
      /* preventDefault, so one Escape does not also close a dialog behind this
         layer or leave a native full-screen. Every layer answers the same way. */
      if (e.key === 'Escape') { e.preventDefault(); onCloseRef.current() }
    }
    document.addEventListener('mousedown', onDown)
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('mousedown', onDown)
      document.removeEventListener('keydown', onKey)
    }
  }, [open, onCloseRef, staysRef])
}

import { useEffect, useRef } from 'react'
import { useLatest } from './useLatest'

/**
 * FOCUS GOES INTO A LAYER WHEN IT OPENS, AND COMES BACK WHEN IT CLOSES.
 *
 * Both halves, because the second one is the half that gets forgotten.
 * <Dropdown> had written both by hand; <CommandPalette> had written the first
 * and not the second, so closing the palette with Escape left focus on the
 * document body and dropped a keyboard user at the top of the page (SC 2.4.3).
 * Nothing in the gate could see it — the markup is correct either way — and it
 * was found by putting the two side by side, which is what lint:mechanism is
 * for. (2026-09-03)
 *
 * The layer is portalled and mounts a tick after `open`, so the target is asked
 * for on the next frame rather than in the effect: a ref that does not exist yet
 * reads as null and the focus lands nowhere.
 *
 * `ready` is for a caller whose target appears later still — a menu that has to
 * measure itself before it has items to focus.
 */
export function useFocusInside({ open, ready = true, target }: {
  open: boolean
  ready?: boolean
  /** The element that should hold focus while the layer is open. */
  target: () => HTMLElement | null
}) {
  const returnTo = useRef<HTMLElement | null>(null)
  /* The caller writes `target` as a closure, so it is a new function on every
   * render. Depending on it re-ran this effect after every keystroke and put
   * focus back on the first row — the arrow keys stopped working, which is how
   * it was found (2026-09-03). The effect depends on OPENING, not on the
   * identity of the getter. */
  const targetRef = useLatest(target)

  useEffect(() => {
    if (!open || !ready) return
    /* Remembered before focus moves, and only once per opening: re-reading it
     * on a later render would remember something inside the layer itself. */
    returnTo.current ??= document.activeElement instanceof HTMLElement ? document.activeElement : null
    /* NOW IF IT IS THERE, NEXT FRAME IF IT IS NOT. A field inside a layer that
     * renders with `open` exists already, and waiting a frame for it would move
     * focus after the reader has started typing; a menu item inside a portal
     * that mounts a tick later does not exist yet, and focusing now would land
     * on nothing. Both are real callers, so both are answered. */
    const el = targetRef.current()
    if (el) { el.focus(); return }
    const raf = requestAnimationFrame(() => { targetRef.current()?.focus() })
    return () => cancelAnimationFrame(raf)
  }, [open, ready, targetRef])

  useEffect(() => {
    if (open) return
    const back = returnTo.current
    returnTo.current = null
    /* Only if it is still there: a menu item that opened a dialog and then
     * unmounted cannot take focus back, and asking it to would move focus to
     * the body — the thing this hook exists to prevent. */
    if (back?.isConnected) back.focus()
  }, [open])
}

import { useCallback, useState, type KeyboardEvent } from 'react'
import { useListKeys } from './useListKeys'

/**
 * AN ACTIVE ROW IN A LIST, MOVED BY THE KEYBOARD — the second mechanism this
 * system had written more than once.
 *
 * Three components carried their own copy (<Combobox>, <CommandPalette>,
 * <ContextMenu>), each a chain of `if (e.key === 'ArrowDown')` with the same
 * `Math.min` / `Math.max` clamp, and all three drifted the same way: none of
 * them answered Home or End, which the ARIA listbox and menu patterns both ask
 * for and which <Dropdown> has always had. Measured 2026-08-31. One hook, and
 * all three gain the two keys they were missing.
 *
 * NOT for <Dropdown>. Its items are real buttons and it moves real DOM focus
 * between them, which is the menu pattern; this is the `aria-activedescendant`
 * pattern, where focus stays in the input and an index says which row is
 * current. Two genuinely different models, and folding them together would make
 * one of them wrong — the same reason `useDismiss` is separate from
 * `useAnchoredLayer`.
 *
 * `handleKey` returns whether it took the event, so the caller keeps its own
 * keys: Backspace removes a token in a Combobox, Space selects in a menu, and
 * Escape means something different in each.
 */
export function useListNavigation({ count, onEnter }: {
  /** How many rows there are RIGHT NOW. The list shrinks as a query narrows it,
   *  so the index is clamped on every move rather than trusted. */
  count: number
  /** Enter on the active row. Left out where the caller commits some other way. */
  onEnter?: (index: number) => void
}) {
  const [active, setActive] = useState(0)

  /* The four keys that walk a bounded list are not this pattern's own: they are
     the same in a menu, a tree and a listbox, and useListKeys owns them for all
     three (2026-09-02). What stays here is what makes this the activedescendant
     pattern — the index is state, and Enter commits it. */
  const listKeys = useListKeys({ count, index: active, move: setActive })

  const handleKey = useCallback((e: KeyboardEvent): boolean => {
    const last = Math.max(0, count - 1)
    if (listKeys(e)) return true
    /* One key left after the four went into the shared mechanism, and it is the
     * one that commits: Enter reads the active row and hands it over. */
    if (e.key !== 'Enter' || !onEnter || count === 0) return false
    e.preventDefault()
    setActive((i) => { onEnter(Math.min(i, last)); return i })
    return true
  }, [count, onEnter, listKeys])

  return { active, setActive, handleKey }
}

import { useCallback, useSyncExternalStore } from 'react'

/**
 * Subscribe to a CSS media query. Returns whether it currently matches.
 *
 * `useSyncExternalStore` rather than state plus an effect, because that is what
 * this is: a value that lives outside React and changes without React being
 * told. The effect version seeded state from `matchMedia` and then set it again
 * on mount, which is a second render on every component that asks — and the
 * render in between held a value read before the subscription existed, which is
 * the tearing this hook is meant to prevent (2026-08-28).
 */
export function useMediaQuery(query: string): boolean {
  const subscribe = useCallback(
    (onChange: () => void) => {
      const mql = window.matchMedia(query)
      mql.addEventListener('change', onChange)
      return () => mql.removeEventListener('change', onChange)
    },
    [query],
  )

  return useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    /* Server snapshot: no window, so nothing matches. The components that ask
       are the ones that widen a layout, and the narrow arrangement is the one
       that is correct when nothing is known. */
    () => false,
  )
}

import { useCallback, useEffect, useRef } from 'react'

/**
 * ONE PENDING TIMEOUT, cleared before the next one and on unmount.
 *
 * Every layer that opens on hover needs exactly this and both of them wrote it:
 * <Tooltip> waits out its delay before appearing, <HoverCard> waits before
 * appearing and again before closing so the pointer can travel onto the card.
 * Six lines each, and the sixth is the one that matters — clearing the pending
 * timer when the component goes away, without which a hover that ends in a
 * navigation sets state on something that is no longer there.
 *
 * Not a hover mechanism: a hover mechanism would have to decide what "intent"
 * means, and the two callers mean different things by it. This owns the timer
 * and nothing else, which is the part they actually shared. (2026-09-03)
 */
export function useTimer() {
  const timer = useRef<number | null>(null)

  const cancel = useCallback(() => {
    if (timer.current !== null) {
      window.clearTimeout(timer.current)
      timer.current = null
    }
  }, [])

  /** Run `fn` after `ms`, replacing whatever was pending. */
  const after = useCallback((ms: number, fn: () => void) => {
    cancel()
    timer.current = window.setTimeout(() => {
      timer.current = null
      fn()
    }, ms)
  }, [cancel])

  useEffect(() => cancel, [cancel])

  return { after, cancel }
}

import { useCallback, type KeyboardEvent } from 'react'
import { useListKeys } from './useListKeys'

/**
 * THE KEYBOARD OF A TREE — the third mechanism this system had written twice.
 *
 * <Tree> and <TreeTable> both answer the ARIA tree pattern, and both wrote it
 * out by hand: Down and Up move one row, Right opens a closed branch or steps
 * into an open one, Left closes an open branch or climbs to its parent. Same six
 * decisions, two files, and they had already drifted the way copies do —
 * <Tree> answered neither Home nor End, which the pattern names and <TreeTable>
 * had (measured 2026-09-02, the day lint:mechanism started reporting the pair).
 * Written once, <Tree> gains the two keys by arriving.
 *
 * EVERYTHING IS AN INDEX INTO THE VISIBLE ROWS, which is what makes one hook
 * cover both. <Tree> thinks in node ids and <TreeTable> in row numbers, but both
 * flatten to the list a reader actually walks, and in that list "the first child
 * of an open branch" is simply the next row. The caller keeps ownership of what
 * a row IS: this hook never touches the DOM, it says which index should have
 * focus and the caller moves it.
 *
 * FOCUS MOVES SYNCHRONOUSLY, in the caller's `move`, not in an effect — a single
 * "ArrowDown then Enter" has to land the Enter on the row that just arrived.
 * Both components had already learned that separately; the comment survives here
 * so the next caller does not learn it a third time.
 *
 * Enter and Space are deliberately NOT here. <Tree> selects on them, <TreeTable>
 * toggles, and folding two commit semantics into one would make one of them
 * wrong — the same reason useListNavigation stays out of <Dropdown> and
 * useDismiss stays out of useAnchoredLayer. `handleKey` returns whether it took
 * the event, so a caller keeps every key this hook did not answer.
 */
export function useTreeKeys({ count, index, isBranch, isOpen, parentIndex, move, toggle }: {
  /** How many rows are VISIBLE right now — a closed branch hides its children,
   *  so this changes as the reader opens and closes things. */
  count: number
  /** The row that currently has focus, as an index into those visible rows. */
  index: number
  isBranch: (index: number) => boolean
  isOpen: (index: number) => boolean
  /** The row that contains this one, or -1 at the top level. */
  parentIndex: (index: number) => number
  /** Put focus on this row. The caller clamps nothing; this hook does. */
  move: (index: number) => void
  toggle: (index: number) => void
}) {
  const listKeys = useListKeys({ count, index, move })

  return useCallback((e: KeyboardEvent): boolean => {
    if (count === 0 || index < 0) return false
    const last = Math.max(0, count - 1)
    const at = (i: number) => move(Math.max(0, Math.min(last, i)))
    const branch = isBranch(index)

    /* Down, Up, Home and End are not a tree's own idea: they walk any bounded
       list, and useListKeys owns them for all three callers. What is left here
       is what makes a tree a tree. */
    if (listKeys(e)) return true

    switch (e.key) {
      case 'ArrowRight':
        e.preventDefault()
        if (branch && !isOpen(index)) toggle(index)
        else if (branch) at(index + 1)
        return true
      case 'ArrowLeft': {
        e.preventDefault()
        if (branch && isOpen(index)) { toggle(index); return true }
        const parent = parentIndex(index)
        if (parent >= 0) at(parent)
        return true
      }
      default:
        return false
    }
  }, [count, index, isBranch, isOpen, parentIndex, move, toggle, listKeys])
}

